    local ItemList = {};
    for i=1, UseNum do
        local DropRes = GiftPackManager:GetGiftPackDropList(GiftPackID);
        for ItemID, ItemNum in pairs(DropRes) do
            if ItemList[ItemID] == nil then
                ItemList[ItemID] = ItemNum;
            else
                ItemList[ItemID] = ItemList[ItemID] + ItemNum;
